#nullable enable // autogenerated

using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using SFB;
using UnityEngine;


namespace MVZ2.IO
{
    public static class FileHelper
    {
        public static void ValidateDirectoryExists(string filePath)
        {
            var dir = Path.GetDirectoryName(filePath);

            if (!Directory.Exists(dir))
            {
                Directory.CreateDirectory(dir);
            }
        }
        public static string CombineFullPath(string rootPath, params string[] filePaths)
        {
            // 1. 获取 rootPath 的标准绝对路径，并确保以分隔符结尾
            var fullRootPath = GuaranteeDirectoryEndsWithSeparator(Path.GetFullPath(rootPath));

            if (filePaths == null || filePaths.Length == 0)
            {
                return fullRootPath;
            }

            // 2. 将所有子路径拼接在一起（Path.Combine 原生支持传入数组或多参数）
            var relativePath = Path.Combine(filePaths);

            // 3. 计算最终的唯一绝对路径（展开所有的 .. 和 .）
            return Path.GetFullPath(Path.Combine(fullRootPath, relativePath));
        }
        public static string CombineFullPathSecure(string rootPath, params string[] filePaths)
        {
            var fullRootPath = GuaranteeDirectoryEndsWithSeparator(Path.GetFullPath(rootPath));

            var fullTargetPath = CombineFullPath(rootPath, filePaths);

            ThrowIfZipSlip(fullTargetPath, fullRootPath);

            return fullTargetPath;
        }
        public static string GuaranteeDirectoryEndsWithSeparator(string directory)
        {
            if (!directory.EndsWith(Path.DirectorySeparatorChar.ToString()) &&
                !directory.EndsWith(Path.AltDirectorySeparatorChar.ToString()))
            {
                directory += Path.DirectorySeparatorChar;
            }
            return directory;
        }
        public static void ThrowIfZipSlip(string fullPath, string fullRootPath)
        {
            if (CheckZipSlip(fullPath, fullRootPath))
            {
                throw new InvalidDataException("Zip entry escapes extraction root.");
            }
        }
        public static bool CheckZipSlip(string fullPath, string fullRootPath)
        {
            // 确保最终解压目标路径依然严格位于 fullRootPath 目录下
            return !fullPath.StartsWith(fullRootPath, StringComparison.OrdinalIgnoreCase);
        }
        public static void Move(string src, string dest, bool overwrite = false)
        {
            if (overwrite)
            {
                if (File.Exists(dest))
                {
                    File.Delete(dest);
                }
            }
            File.Move(src, dest);
        }
        public static void WriteBytes(Stream stream, byte[] bytes)
        {
            stream.Write(bytes, 0, bytes.Length);
        }
        public static Task<string?> OpenExternalFile(string[] extensions, Action<string> importAction)
        {
#if UNITY_STANDALONE_OSX || UNITY_STANDALONE_WIN || UNITY_STANDALONE_LINUX || UNITY_EDITOR
            var selectedPathes = StandaloneFileBrowser.OpenFilePanel("", "", extensions.Select(e => new ExtensionFilter(string.Empty, extensions)).ToArray(), false);
            if (selectedPathes.Length == 0)
                return Task.FromResult<string?>(null);
            var importPath = selectedPathes[0];
            importAction?.Invoke(importPath);
            return Task.FromResult<string?>(importPath);
#elif UNITY_IOS || UNITY_ANDROID
            var t = new TaskCompletionSource<string?>();
            var fileTypes = extensions.Select(e => NativeFilePicker.ConvertExtensionToFileType(e)).ToArray();
            NativeFilePicker.PickFile(path => {
                if (!string.IsNullOrEmpty(path))
                {
                    importAction?.Invoke(path);
                }
                t.SetResult(path);
            }, fileTypes);
            return t.Task;
#else
            return Task.FromResult<string?>(null);
#endif
        }
        public static async Task<string?> SaveExternalFile(string defaultName, string[] extensions, Action<string> saveAction)
        {
#if UNITY_STANDALONE_OSX || UNITY_STANDALONE_WIN || UNITY_STANDALONE_LINUX || UNITY_EDITOR
            var exportPath = StandaloneFileBrowser.SaveFilePanel("", "", defaultName, extensions.Select(e => new ExtensionFilter(string.Empty, e)).ToArray());
            if (string.IsNullOrEmpty(exportPath))
                return null;
            saveAction?.Invoke(exportPath);
            await Task.CompletedTask;
            return exportPath;
#elif UNITY_IOS || UNITY_ANDROID
            // 这个插件是先写出再复制到目标目录的
            var fileName = defaultName;
            if (extensions.Length > 0)
            {
                fileName = $"{fileName}.{extensions[0]}";
            }
            var tempPath = Path.Combine(Application.temporaryCachePath, fileName);
            saveAction?.Invoke(tempPath);

            if (!File.Exists(tempPath))
            {
                return null;
            }

            var t = new TaskCompletionSource<string?>();
            NativeFilePicker.ExportFile(tempPath, success => t.SetResult(success ? fileName : null));
            var exportPath = await t.Task;
            File.Delete(tempPath); // 清理临时文件
            return exportPath;
#else
            await Task.CompletedTask;
            return null;
#endif
        }
        public static string GetFilePathURL(string filePath)
        {
            // 1. 根据不同平台，对文件路径进行格式化
            if (Application.platform == RuntimePlatform.Android)
            {
                // Android平台下，路径不需要 "file://" 前缀
                // 音频文件需要放在StreamingAssets文件夹下
                return Path.Combine(Application.streamingAssetsPath, filePath);
            }
            else
            {
                // 其他平台（如Windows, iOS），需要添加 "file://" 前缀
                return "file://" + filePath;
            }
        }
        public static string RemoveExtension(string filePath)
        {
            return Path.ChangeExtension(filePath, string.Empty).TrimEnd('.');
        }
    }
}
